(() => {
  const $ = (id) => document.getElementById(id);
  const params = new URLSearchParams(location.search);
  const currentConv = () => window.sidecar?.conversationId || params.get('conversationId') || '';

  // Single-track zero-overlap Nyaa audio player (Web Audio API + HTMLAudio fallback)
  const NYAA_B64 = '';
  const NYAA_DATA_URI = 'data:audio/wav;base64,' + NYAA_B64;

  let audioCtx = null;
  let nyaaBuffer = null;
  let activeSource = null;
  const fallbackAudio = new Audio(NYAA_DATA_URI);
  fallbackAudio.preload = 'auto';

  function decodeBase64ToArrayBuffer(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }

  function initAudioContext() {
    if (!audioCtx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (Ctx) {
        audioCtx = new Ctx();
        audioCtx
          .decodeAudioData(decodeBase64ToArrayBuffer(NYAA_B64))
          .then((buf) => {
            nyaaBuffer = buf;
          })
          .catch(() => {});
      }
    }
    if (audioCtx && audioCtx.state === 'suspended') {
      audioCtx.resume().catch(() => {});
    }
  }

  initAudioContext();

  function playNyaa() {
    initAudioContext();
    if (activeSource) {
      try {
        activeSource.onended = null;
        activeSource.stop(0);
        activeSource.disconnect();
      } catch {}
      activeSource = null;
    }
    try {
      fallbackAudio.pause();
      fallbackAudio.currentTime = 0;
    } catch {}

    if (audioCtx && nyaaBuffer) {
      const src = audioCtx.createBufferSource();
      src.buffer = nyaaBuffer;
      src.connect(audioCtx.destination);
      activeSource = src;
      src.onended = () => {
        if (activeSource === src) activeSource = null;
      };
      src.start(0);
    } else {
      fallbackAudio.currentTime = 0;
      fallbackAudio.play().catch(() => {});
    }
  }

  async function getJson(path) {
    const f = window.sidecar?.fetch ? window.sidecar.fetch.bind(window.sidecar) : fetch;
    const res = await f(path, { method: 'GET' });
    if (!res.ok) throw new Error(`${path}: ${res.status}`);
    return res.json();
  }

  function fmtTokens(n) {
    const num = Number(n) || 0;
    if (num >= 1_000_000) return (num / 1_000_000).toFixed(2) + 'M';
    if (num >= 10_000) return (num / 1_000).toFixed(1) + 'k';
    if (num >= 1_000) return (num / 1_000).toFixed(2) + 'k';
    return String(num);
  }

  const stage = $('pet-stage');
  const avatar = $('pet-avatar');
  const petImg = $('pet-img') || document.querySelector('.pet-img');
  const speechLine = $('speech-line');
  const dashboard = $('dashboard');
  const pinBtn = $('pin-btn');
  const ctxCapBtn = $('ctx-cap-btn');
  const icoCard = $('ico-card');

  let isPinned = true;
  let isHoveringIco = false;
  let lastSeenChatTotal = null;
  let latestData = null;
  let lineIdx = 0;
  let currentPetKey = 'gemini';
  let currentPetUrl = '';

  function updatePetForModel(activeModel, assetVersion) {
    const m = String(activeModel || '').toLowerCase();
    const nextKey = m.includes('claude') ? 'claude' : 'gemini';
    const ver = assetVersion || 20;
    const nextUrl = nextKey === 'claude' ? `/pet-claude.png?v=20&t=${ver}` : `/pet.png?v=20`;
    if (nextKey !== currentPetKey || nextUrl !== currentPetUrl) {
      const keyChanged = nextKey !== currentPetKey;
      currentPetKey = nextKey;
      currentPetUrl = nextUrl;
      if (petImg) {
        petImg.src = nextUrl;
      }
      if (keyChanged) {
        ctxCapIdx = nextKey === 'claude' ? 0 : 1;
        userChoseCap = false;
        triggerBounce();
      }
    }
  }

  // Context window cap options: 200k (Claude/GPT/standard) or 1M (Gemini)
  const CTX_CAPS = [200_000, 1_000_000];
  let ctxCapIdx = 0;
  let userChoseCap = false;

  try {
    const savedCap = Number(localStorage.getItem('gemini_pet_ctx_cap') || '0');
    if (savedCap === 1_000_000) {
      ctxCapIdx = 1;
      userChoseCap = true;
    } else if (savedCap === 200_000) {
      ctxCapIdx = 0;
      userChoseCap = true;
    }
  } catch {}

  function fallbackBreakdown(lastStep, totals) {
    const totalCtx = Number(lastStep?.total) || 0;
    if (totalCtx <= 0) {
      return {
        toolsTokens: 0,
        messagesTokens: 0,
        systemTokens: 0,
        thinkingTokens: 0,
        toolsPct: 0,
        messagesPct: 0,
        systemPct: 0,
        thinkingPct: 0,
      };
    }
    const systemTokens = Math.min(totalCtx, 16000);
    const dynamic = Math.max(0, totalCtx - systemTokens);
    const outShare = Math.min(0.45, Math.max(0.12, (Number(totals?.output) || 0) / Math.max(1, Number(totals?.input) + Number(totals?.output))));
    const messagesTokens = Math.round(dynamic * outShare * 0.7);
    const thinkingTokens = Math.round(dynamic * outShare * 0.3);
    const toolsTokens = Math.max(0, dynamic - messagesTokens - thinkingTokens);

    const toolsPct = Math.round((toolsTokens / totalCtx) * 100);
    const messagesPct = Math.round((messagesTokens / totalCtx) * 100);
    const systemPct = Math.round((systemTokens / totalCtx) * 100);
    const thinkingPct = Math.max(0, 100 - toolsPct - messagesPct - systemPct);
    return { toolsTokens, messagesTokens, systemTokens, thinkingTokens, toolsPct, messagesPct, systemPct, thinkingPct };
  }

  function renderContextWindow(currentChat) {
    const lastStep = currentChat?.lastStep || { input: 0, cache: 0, output: 0, total: 0 };
    if (!userChoseCap && currentChat?.contextLimit) {
      ctxCapIdx = currentChat.contextLimit >= 1_000_000 ? 1 : 0;
    }
    const cap = CTX_CAPS[ctxCapIdx];
    const capLabel = cap >= 1_000_000 ? '1M' : '200k';
    if (ctxCapBtn) {
      ctxCapBtn.textContent = `Cap: ${capLabel} ⇄`;
    }

    const used = Number(lastStep.total) || 0;
    const rawPct = Math.round((used / cap) * 100);
    const barPct = Math.min(100, Math.max(used > 0 ? 2 : 0, rawPct));

    $('ctx-status-label').textContent = 'Active Context Size';
    $('val-ctx-window').textContent = `${fmtTokens(used)} / ${capLabel} (${rawPct}%)`;
    $('bar-ctx').style.width = `${barPct}%`;

    const compactedNote = currentChat?.compactedFrom ? ` · Auto-compacted @ ${fmtTokens(currentChat.compactedFrom)}` : '';
    const compactHint = rawPct >= 80 ? ' · 💡 Try /compact' : '';
    $('sub-ctx').textContent = `Cached: ${fmtTokens(lastStep.cache)} · New In: ${fmtTokens(lastStep.input)} · Out: ${fmtTokens(lastStep.output)}${compactedNote}${compactHint}`;

    // Hover Tooltip Breakdown (%)
    const bd = currentChat?.contextBreakdown || fallbackBreakdown(lastStep, currentChat?.totals);
    $('tip-ctx-total').textContent = `${fmtTokens(used)} tokens`;
    $('seg-tools').style.width = `${bd.toolsPct}%`;
    $('seg-msgs').style.width = `${bd.messagesPct}%`;
    $('seg-sys').style.width = `${bd.systemPct}%`;
    $('seg-think').style.width = `${bd.thinkingPct}%`;

    $('tip-tools').textContent = `${bd.toolsPct}% (${fmtTokens(bd.toolsTokens)})`;
    $('tip-msgs').textContent = `${bd.messagesPct}% (${fmtTokens(bd.messagesTokens)})`;
    $('tip-sys').textContent = `${bd.systemPct}% (${fmtTokens(bd.systemTokens)})`;
    $('tip-think').textContent = `${bd.thinkingPct}% (${fmtTokens(bd.thinkingTokens)})`;
  }

  function renderIcoCard(data) {
    if (!data) return;
    const lastTurn = data.currentChat?.lastTurn || { input: 0, cache: 0, output: 0, total: 0 };
    const chatTotals = data.currentChat?.totals || { input: 0, cache: 0, output: 0, total: 0 };
    const chatWeek = data.currentChat?.weeklyTotals || chatTotals;
    const daily = data.daily || data.last5h || { input: 0, cache: 0, output: 0, total: 0, steps: 0 };
    const week = data.thisWeek || { input: 0, cache: 0, output: 0, total: 0, steps: 0 };

    const activeSource = isHoveringIco ? chatWeek : week;
    const totalActive = Math.max(1, activeSource.total);

    const inPct = Math.min(100, Math.round((activeSource.input / totalActive) * 100));
    const cachePct = Math.min(100, Math.round((activeSource.cache / totalActive) * 100));
    const realOutPct = Math.round((activeSource.output / totalActive) * 100);
    const outBarPct = Math.min(100, Math.max(activeSource.output > 0 ? 2 : 0, realOutPct));

    if ($('ico-title')) {
      $('ico-title').textContent = isHoveringIco
        ? 'This Chat (Weekly) · Input · Cache · Output'
        : 'Weekly Input · Cache · Output Tokens';
    }
    if ($('lbl-in-type')) $('lbl-in-type').textContent = isHoveringIco ? 'Input (This Chat)' : 'Input Tokens';
    if ($('lbl-cache-type')) $('lbl-cache-type').textContent = isHoveringIco ? 'Cache (This Chat)' : 'Cache Tokens';
    if ($('lbl-out-type')) $('lbl-out-type').textContent = isHoveringIco ? 'Output (This Chat)' : 'Output Tokens';

    $('cache-hit-badge').textContent = `Cache: ${cachePct}%`;

    $('tok-in-week').textContent = `${fmtTokens(activeSource.input)} (${inPct}%)`;
    $('bar-in').style.width = `${inPct}%`;
    $('sub-in').textContent = `Daily: ${fmtTokens(daily.input)} · Chat: ${fmtTokens(chatTotals.input)} · Reply: ${fmtTokens(lastTurn.input)}`;

    $('tok-cache-week').textContent = `${fmtTokens(activeSource.cache)} (${cachePct}%)`;
    $('bar-cache').style.width = `${cachePct}%`;
    $('sub-cache').textContent = `Daily: ${fmtTokens(daily.cache)} · Chat: ${fmtTokens(chatTotals.cache)} · Reply: ${fmtTokens(lastTurn.cache)}`;

    $('tok-out-week').textContent = `${fmtTokens(activeSource.output)} (${realOutPct}%)`;
    $('bar-out').style.width = `${outBarPct}%`;
    $('sub-out').textContent = `Daily: ${fmtTokens(daily.output)} · Chat: ${fmtTokens(chatTotals.output)} · Reply: ${fmtTokens(lastTurn.output)}`;
  }

  if (icoCard) {
    icoCard.addEventListener('mouseenter', () => {
      isHoveringIco = true;
      if (latestData) renderIcoCard(latestData);
    });
    icoCard.addEventListener('mouseleave', () => {
      isHoveringIco = false;
      if (latestData) renderIcoCard(latestData);
    });
  }

  if (ctxCapBtn) {
    ctxCapBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      userChoseCap = true;
      ctxCapIdx = (ctxCapIdx + 1) % CTX_CAPS.length;
      try {
        localStorage.setItem('gemini_pet_ctx_cap', String(CTX_CAPS[ctxCapIdx]));
      } catch {}
      if (latestData) renderContextWindow(latestData.currentChat);
    });
  }

  pinBtn.addEventListener('click', () => {
    isPinned = !isPinned;
    pinBtn.classList.toggle('active', isPinned);
    pinBtn.textContent = isPinned ? '📌 Pinned' : '📌 Unpinned';
    if (isPinned) {
      dashboard.classList.remove('collapsed');
    }
  });

  function triggerBounce() {
    avatar.classList.remove('bounce');
    void avatar.offsetWidth;
    avatar.classList.add('bounce');
  }

  stage.addEventListener('click', () => {
    playNyaa();
    triggerBounce();
    if (!isPinned) {
      dashboard.classList.toggle('collapsed');
    }
    if (!latestData) return;
    const lastTurn = latestData.currentChat?.lastTurn || { input: 0, cache: 0, output: 0, total: 0 };
    const lastStep = latestData.currentChat?.lastStep || { input: 0, cache: 0, output: 0, total: 0 };
    const week = latestData.thisWeek || { input: 0, cache: 0, output: 0, total: 0 };

    const lines = [
      `Nyaa~ Context window is at ${fmtTokens(lastStep.total)} tokens! ✨`,
      `Nyaa~ Last reply: In ${fmtTokens(lastTurn.input)} · Cache ${fmtTokens(lastTurn.cache)} · Out ${fmtTokens(lastTurn.output)} 💙`,
      `Nyaa~ This week: ${fmtTokens(week.total)} total (${fmtTokens(week.cache)} cached!) 🌟`,
      isPinned ? `Unpin 📌 at the top if you want click-to-hide! 🐾` : `Click me anytime to toggle the panel! 🐾`,
    ];
    lineIdx = (lineIdx + 1) % lines.length;
    speechLine.textContent = lines[lineIdx];
  });

  async function poll() {
    try {
      const conv = currentConv();
      const q = conv ? `?conversationId=${encodeURIComponent(conv)}` : '';
      const data = await getJson(`/api/usage${q}`);
      latestData = data;

      $('status-badge').textContent = data.ok ? 'Live' : 'Error';
      const cid = data.currentChat?.convId || data.conversationId;
      $('val-conv').textContent = cid ? cid.slice(0, 8) : 'auto';

      const lastTurn = data.currentChat?.lastTurn || { input: 0, cache: 0, output: 0, total: 0 };
      const chatTotals = data.currentChat?.totals || { input: 0, cache: 0, output: 0, total: 0 };
      const daily = data.daily || data.last5h || { input: 0, cache: 0, output: 0, total: 0, steps: 0 };
      const week = data.thisWeek || { input: 0, cache: 0, output: 0, total: 0, steps: 0 };

      // Pet speech bubble live chat pill
      $('val-last-reply').textContent = fmtTokens(lastTurn.total);
      $('val-chat-total').textContent = fmtTokens(chatTotals.total);

      // Card 1: Overall Token Usage (This Week & Daily)
      $('val-week').textContent = fmtTokens(week.total);
      $('sub-week').textContent = `${week.steps || 0} replies across ${data.conversationCount || 0} chats`;

      $('val-5h').textContent = fmtTokens(daily.total);
      $('sub-5h').textContent = `${daily.steps || 0} replies today`;

      // Switch pet image if active model changed (Gemini <-> Claude)
      updatePetForModel(data.currentChat?.activeModel, data.assetVersion);

      // Card 2: Weekly Input, Cache, Output Breakdown (Hover switches to This Chat This Week)
      renderIcoCard(data);

      // Card 3: Current Chat Context Window + Hover Composition
      renderContextWindow(data.currentChat);

      if (lastSeenChatTotal !== null && chatTotals.total > lastSeenChatTotal) {
        triggerBounce();
        speechLine.textContent = `Reply: In ${fmtTokens(lastTurn.input)} · Cache ${fmtTokens(lastTurn.cache)} · Out ${fmtTokens(lastTurn.output)} ✨`;
      } else if (lastSeenChatTotal === null && lastTurn.total > 0) {
        speechLine.textContent = `Reply: In ${fmtTokens(lastTurn.input)} · Cache ${fmtTokens(lastTurn.cache)} · Out ${fmtTokens(lastTurn.output)} ✨`;
      }
      lastSeenChatTotal = chatTotals.total;
    } catch (err) {
      $('status-badge').textContent = 'Offline';
    }
  }

  poll();
  setInterval(poll, 1500);
})();
